mapper.select:
SELECT T1.REGIST_SEQNO AS registSeqno, ifnull(T1.UPDATE_TIME,T1.CREATE_TIME) AS statusDate, T1.LAST_HOLD_DAY AS lastHoldDay, T1.PRD_REGIST_CODE AS prodId, T1.PROD_NAME AS prodName, T1.MANAGER AS manager, T1.PROD_TYPE AS prodType, T1.PROD_INVEST_TYPE AS prodInvestType, T1.RAISE_TYPE AS raiseType, T1.TERMID AS termid, T1.PROD_SCALE AS prodScale, T1.INBANK_BONDMARK_HOLD_DENOMINA AS inbankBondmarkHoldDenomina, T1.INBANK_BONDMARK_HOLD_RATIO AS inbankBondmarkHoldRatio, T1.HOLDER_NAME AS holderName, T1.HOLDER_TYPE AS holderType, T1.INVEST_AMOUNT AS investAmount, T1.INVEST_RATIO AS investRatio, T1.TWO_HOLDER_NAME AS twoHolderName, T1.TWO_HOLDER_TYPE AS twoHolderType, T1.TWO_INVEST_AMOUNT AS twoInvestAmount, T1.TWO_INVEST_RATIO AS twoInvestRatio, T1.PROD_SHARE AS prodShare, T1.HOLDER_SHARE AS holderShare, T1.REMARK AS remark FROM CHB_CONSIGNOR_DETAIL_SUB T1
1=1
AND ( T1.PROD_ID LIKE concat(concat('%',#{prodId,jdbcType=VARCHAR}),'%') OR T1.PRD_REGIST_CODE LIKE concat(concat('%',#{prodId,jdbcType=VARCHAR}),'%') )
AND T1.RAISE_TYPE = #{raiseType,jdbcType=VARCHAR}
AND T1.HOLDER_TYPE = #{holderType,jdbcType=VARCHAR}
and DATE_FORMAT(ifnull(T1.UPDATE_TIME,T1.CREATE_TIME),'%Y-%m-%d') >= #{statusDateStart}
and DATE_FORMAT(ifnull(T1.UPDATE_TIME,T1.CREATE_TIME),'%Y-%m-%d') <= #{statusDateEnd}
and DATE_FORMAT(T1.LAST_HOLD_DAY,'%Y-%m-%d') = #{lastDayHold}

SELECT
    COUNT(*)
FROM
    CHB_CONSIGNOR_DETAIL_SUB T1

    1=1

        AND (
        T1.PROD_ID LIKE concat(concat('%',#{prodId,jdbcType=VARCHAR}),'%')
        OR
        T1.PRD_REGIST_CODE LIKE concat(concat('%',#{prodId,jdbcType=VARCHAR}),'%')
        )


        AND T1.RAISE_TYPE = #{raiseType,jdbcType=VARCHAR}


        AND T1.HOLDER_TYPE = #{holderType,jdbcType=VARCHAR}


        and DATE_FORMAT(ifnull(T1.UPDATE_TIME,T1.CREATE_TIME),'%Y-%m-%d') >= #{statusDateStart}


        and DATE_FORMAT(ifnull(T1.UPDATE_TIME,T1.CREATE_TIME),'%Y-%m-%d') <= #{statusDateEnd}


        and DATE_FORMAT(T1.LAST_HOLD_DAY,'%Y-%m-%d') = #{lastDayHold}
